document.addEventListener("astro:page-load",()=>{const e=document.getElementById("back-to-top");if(!e)return;const o=()=>{(window.scrollY||document.documentElement.scrollTop)>500?e.classList.add("is-visible"):(e.classList.remove("is-visible"),e.blur())};window.addEventListener("scroll",o,{passive:!0}),e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}),o()});
